def doc_html(yaz):
    return io.open(os.path.join(TUT, 'zhaloby_konflikt_doc.%s.html' % yaz), encoding='utf-8').read().strip()


def shag(yaz):
    t = T[yaz]
    tab = ('<div class="scroller"><table><thead><tr>' + ''.join('<th>' + x + '</th>' for x in t['tab']) + '</tr></thead><tbody>'
           + ''.join('<tr>' + ''.join('<td>' + x + '</td>' for x in r) + '</tr>' for r in t['stroki']) + '</tbody></table></div>')
    keis = lambda k, r: ('<div class="keis"><span class="tag">' + t['keis_tag'] + '</span><p>' + k + '</p><details><summary>' + t['razbor']
                         + '</summary><p>' + r + '</p></details></div>')
    html = ('<p>' + t['vvod'] + '</p>'
            + '<h3>' + t['h1'] + '</h3><p>' + t['p1'] + '</p>' + tab
            + '<div class="primer"><span class="tag">' + t['skazat_tag'] + '</span><p>' + t['skazat'] + '</p></div>'
            + '<h3>' + t['h2'] + '</h3><p>' + t['p2'] + '</p><ul>' + ''.join('<li>' + x + '</li>' for x in t['ul']) + '</ul>'
            + '<h3>' + t['h3'] + '</h3><ul>' + ''.join('<li>' + x + '</li>' for x in t['video']) + '</ul>'
            + '<div class="pitfall"><span class="tag">' + t['nelzya_tag'] + '</span><p>' + t['nelzya'] + '</p></div>'
            + keis(t['k1'], t['r1']) + keis(t['k2'], t['r2'])
            + '<details class="verify" style="margin-top:26px"><summary>' + t['doc'] + '</summary>'
            '<div class="docfull" style="max-height:420px;overflow-y:auto;padding:0 8px 0 14px;border-left:2px solid var(--line);'
            'font-size:14px;line-height:1.5">' + doc_html(yaz) + '</div></details>')
    return dict(rail=t['rail'], title=t['title'], html=html, q=t['q'], opts=t['opts'], right=1, why=t['why'])


